CREATE OR REPLACE FUNCTION public.confirm_payway_subscription_order(p_business_id uuid, p_order_id uuid, p_tran_id text, p_amount numeric, p_currency text, p_apv text DEFAULT NULL::text, p_payment_type text DEFAULT NULL::text, p_bank_ref text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.subscription_orders%rowtype;
  b public.businesses%rowtype;
  v_monthly numeric;
  v_discount numeric;
  v_matched text;
  v_apply jsonb;
  v_currency text;
  v_expected_proration numeric:=0;
  v_expected_proration_seconds bigint:=0;
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'Service-role payment verification required.';
  end if;

  if p_business_id is null or p_order_id is null or coalesce(trim(p_tran_id),'')='' then
    raise exception 'PayWay order reference is required.';
  end if;

  select * into o
  from public.subscription_orders
  where id=p_order_id and business_id=p_business_id
  for update;

  if not found then raise exception 'Subscription order not found.'; end if;

  if o.status='approved' and o.payway_verified_at is not null then
    if o.payway_tran_id is distinct from p_tran_id then
      raise exception 'PayWay transaction does not match the approved order.';
    end if;
    return jsonb_build_object(
      'status','approved',
      'alreadyConfirmed',true,
      'effective_at',o.effective_at,
      'activated_at',o.activated_at
    );
  end if;

  if o.status <> 'pending_payment' then
    raise exception 'This subscription order is not waiting for payment.';
  end if;
  if o.pricing_version not in (5,6,7) then
    raise exception 'Unsupported subscription checkout version.';
  end if;
  if o.payment_provider is distinct from 'aba_payway' then
    raise exception 'This subscription order is not locked to ABA PayWay.';
  end if;
  if o.payway_tran_id is distinct from p_tran_id then
    raise exception 'PayWay transaction does not match this subscription order.';
  end if;
  if o.payway_started_at is null then
    raise exception 'ABA PayWay checkout was not started for this order.';
  end if;
  if o.pricing_locked_until is not null and o.payway_started_at > o.pricing_locked_until then
    raise exception 'The subscription price lock expired before ABA PayWay checkout started.';
  end if;

  v_currency:=upper(coalesce(nullif(trim(p_currency),''),'USD'));
  if v_currency <> upper(coalesce(o.currency,'USD')) then
    raise exception 'PayWay currency does not match the subscription order.';
  end if;
  if round(coalesce(p_amount,-1),2) <> round(coalesce(o.total_amount,-1),2) then
    raise exception 'PayWay amount does not match the subscription order.';
  end if;

  select * into b from public.businesses where id=o.business_id for update;
  if not found then raise exception 'Business not found.'; end if;
  if not b.is_active and coalesce(b.disabled_reason,'') <> 'subscription_expired' then
    raise exception 'Resolve the business suspension before payment activation.';
  end if;

  -- The quote is bound to the business subscription snapshot captured at order
  -- creation. If anything changed independently, do not apply a stale payment.
  if b.subscription_user_limit is distinct from o.current_user_limit
     or b.subscription_plan_key is distinct from o.current_plan_key
     or b.subscription_started_at is distinct from o.current_subscription_started_at
     or b.subscription_expires_at is distinct from o.current_subscription_expires_at then
    raise exception 'Subscription changed after checkout. Contact support before retrying payment.';
  end if;

  if o.plan_key='solo' then
    v_monthly:=10;
  elsif o.plan_key='small_team' then
    v_monthly:=18;
  elsif o.plan_key='growth' then
    v_monthly:=38;
  elsif o.plan_key='custom' then
    v_matched:=case when o.requested_branch_limit=1 then
      case o.requested_user_limit when 1 then 'solo' when 5 then 'small_team' when 10 then 'growth' else null end
      else null end;
    if o.pricing_version=5 then
      v_monthly:=case v_matched
        when 'solo' then 10
        when 'small_team' then 18
        when 'growth' then 38
        else o.requested_user_limit*5 + o.requested_branch_limit*20
      end;
    else
      v_monthly:=public.tenh_custom_plan_monthly_price(o.requested_user_limit,o.requested_branch_limit);
    end if;
  else
    raise exception 'Invalid subscription plan.';
  end if;

  v_discount:=case o.term_months when 3 then 5 when 6 then 8 when 12 then 10 else 0 end;

  if o.order_kind='upgrade' and o.current_monthly_price is not null then
    v_expected_proration_seconds:=greatest(0,floor(extract(epoch from (o.current_subscription_expires_at-o.created_at)))::bigint);
    if abs(coalesce(o.upgrade_proration_seconds,0)-v_expected_proration_seconds)>5 then
      raise exception 'Upgrade proration window does not match the locked subscription expiry.';
    end if;
    v_expected_proration:=round(greatest(0,v_monthly-coalesce(o.current_monthly_price,0))*greatest(0,coalesce(o.upgrade_proration_seconds,0))::numeric/2592000,2);
  end if;

  if o.term_months not in (0,1,3,6,12)
     or o.requested_user_limit not between 1 and 500
     or o.requested_branch_limit not between 1 and 100
     or o.monthly_price <> v_monthly
     or o.discount_percent <> v_discount
     or o.subtotal_amount <> v_monthly*o.term_months
     or o.term_price_amount <> round(o.subtotal_amount*(1-v_discount/100),2)
     or coalesce(o.extension_amount,o.term_price_amount) <> o.term_price_amount
     or coalesce(o.upgrade_prorated_amount,0) <> v_expected_proration
     or o.remaining_credit_amount < 0
     or o.total_amount <> round(o.term_price_amount-o.remaining_credit_amount+v_expected_proration,2) then
    raise exception 'Subscription pricing does not match its configuration.';
  end if;

  if o.order_kind='renewal' and o.remaining_credit_amount <> 0 then
    raise exception 'Next-plan renewal cannot use current-term credit.';
  end if;

  update public.subscription_orders
  set status='approved',
      payment_provider='aba_payway',
      payway_verified_at=now(),
      payway_apv=nullif(trim(p_apv),''),
      payway_payment_type=nullif(trim(p_payment_type),''),
      payway_bank_ref=nullif(trim(p_bank_ref),''),
      payway_payload=coalesce(p_payload,'{}'::jsonb),
      payment_note=coalesce(payment_note,'Verified automatically by ABA PayWay'),
      approved_at=coalesce(approved_at,now()),
      reviewed_at=coalesce(reviewed_at,now()),
      reviewed_by_user_id=null,
      reviewed_by_email='ABA PayWay (automatic)',
      review_note='Verified with ABA PayWay Check Transaction API',
      updated_at=now()
  where id=o.id;

  if coalesce(o.effective_at,now()) <= now() then
    v_apply:=public.tenh_apply_subscription_order(o.id);
    return jsonb_build_object(
      'status','approved',
      'effective_at',o.effective_at,
      'new_expiry',v_apply->>'new_expiry',
      'activated',true
    );
  end if;

  return jsonb_build_object(
    'status','approved',
    'effective_at',o.effective_at,
    'new_expiry',b.subscription_expires_at,
    'activated',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_safe_subscription_order(p_business_id uuid, p_requesting_user_id uuid, p_plan_key text, p_term_months integer, p_requested_user_limit integer, p_requested_branch_limit integer, p_keep_member_ids uuid[] DEFAULT NULL::uuid[], p_keep_branch_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(order_id uuid, order_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b public.businesses%rowtype;
  v_id uuid;
  v_target_users integer;
  v_target_branches integer;
  v_current_users integer;
  v_current_branches integer;
  v_monthly numeric;
  v_discount numeric;
  v_subtotal numeric;
  v_term numeric;
  v_credit numeric:=0;
  v_carryover_seconds bigint:=0;
  v_carryover_source text:='none';
  v_current_monthly numeric:=0;
  v_upgrade_proration numeric:=0;
  v_proration_seconds bigint:=0;
  v_total numeric;
  v_kind text;
  v_effective timestamptz;
  v_matching_plan text;
  v_owner_count integer;
  v_default_count integer;
  v_active_users integer;
  v_active_branches integer;
begin
  if coalesce(auth.role(),'')<>'service_role' then raise exception 'Server access required.'; end if;
  select * into b from public.businesses where id=p_business_id for update;
  if not found or not exists(
    select 1 from public.business_members
    where business_id=p_business_id and user_id=p_requesting_user_id and role::text='owner' and is_active
  ) then raise exception 'Business owner access required.'; end if;

  if p_plan_key not in ('solo','small_team','growth','custom') or p_term_months not in (0,1,3,6,12) then
    raise exception 'Invalid subscription configuration.';
  end if;

  if p_plan_key='solo' then v_target_users:=1; v_target_branches:=1; v_monthly:=10;
  elsif p_plan_key='small_team' then v_target_users:=5; v_target_branches:=1; v_monthly:=18;
  elsif p_plan_key='growth' then v_target_users:=10; v_target_branches:=1; v_monthly:=38;
  else
    if p_requested_user_limit is null or p_requested_user_limit not between 1 and 500
       or p_requested_branch_limit is null or p_requested_branch_limit not between 1 and 100 then
      raise exception 'Choose valid Custom Plan user and branch counts.';
    end if;
    v_target_users:=p_requested_user_limit;
    v_target_branches:=p_requested_branch_limit;
    v_matching_plan:=case when v_target_branches=1 then case v_target_users when 1 then 'solo' when 5 then 'small_team' when 10 then 'growth' else null end else null end;
    v_monthly:=public.tenh_custom_plan_monthly_price(v_target_users,v_target_branches);
  end if;

  if p_plan_key<>'custom' and (p_requested_user_limit is distinct from v_target_users or p_requested_branch_limit is distinct from v_target_branches) then
    raise exception 'Standard plan allowances cannot be customized.';
  end if;

  select count(*) into v_owner_count from public.business_members
  where business_id=b.id and role::text='owner'
    and (is_active or (coalesce(team_password_required,false) and disabled_reason='password_setup'));
  if v_owner_count>v_target_users then raise exception 'The selected plan cannot cover the protected Owner seats.'; end if;
  select count(*) into v_default_count from public.business_locations where business_id=b.id and is_active and is_default;
  if v_default_count>v_target_branches then raise exception 'The selected plan cannot cover the protected Main Branch.'; end if;

  -- Capacity usage is separate from the currently purchased allowance. A plan
  -- change can only become immediate when it expands the paid limits AND still
  -- covers every seat/branch in use. Otherwise it waits for the paid term end,
  -- where the safe keep/disable rules are applied.
  select count(*) into v_active_users
  from public.business_members m
  where m.business_id=b.id
    and coalesce(m.disabled_reason,'')<>'removed_by_owner'
    and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'));

  select count(*) into v_active_branches
  from public.business_locations l
  where l.business_id=b.id and l.is_active and not coalesce(l.plan_disable_pending,false);

  if p_keep_member_ids is not null then
    if exists(
      select 1 from unnest(p_keep_member_ids) x(id)
      where not exists(
        select 1 from public.business_members m where m.id=x.id and m.business_id=b.id
          and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'))
      )
    ) then raise exception 'One of the selected users is no longer active. Refresh Plans.'; end if;
    if (
      select count(*) from public.business_members m
      where m.business_id=b.id and m.id=any(p_keep_member_ids) and m.role::text<>'owner'
    )>greatest(0,v_target_users-v_owner_count) then
      raise exception 'Too many users were selected to stay active for this plan.';
    end if;
  end if;

  if p_keep_branch_ids is not null then
    if exists(
      select 1 from unnest(p_keep_branch_ids) x(id)
      where not exists(select 1 from public.business_locations l where l.id=x.id and l.business_id=b.id and l.is_active)
    ) then raise exception 'One of the selected branches is no longer active. Refresh Plans.'; end if;
    if (
      select count(*) from public.business_locations l
      where l.business_id=b.id and l.id=any(p_keep_branch_ids) and not l.is_default
    )>greatest(0,v_target_branches-v_default_count) then
      raise exception 'Too many branches were selected to stay active for this plan.';
    end if;
  end if;

  if exists(
    select 1 from public.subscription_orders
    where business_id=b.id and pricing_version in (5,6,7) and order_kind='renewal'
      and status='approved' and activated_at is null and effective_at>now()
  ) then raise exception 'A next plan is already paid. You can change which users and branches stay active from Subscription.'; end if;
  if exists(select 1 from public.subscription_orders where business_id=b.id and status='payment_submitted') then
    raise exception 'A payment is already under review.';
  end if;

  v_current_users:=greatest(1,coalesce(b.subscription_user_limit,1));
  v_current_branches:=case when b.subscription_status='active' and b.subscription_plan_key='custom' then greatest(1,coalesce(b.subscription_branch_limit,1)) else 1 end;
  v_current_monthly:=greatest(0,coalesce(
    b.subscription_monthly_price,
    case b.subscription_plan_key
      when 'solo' then 10
      when 'small_team' then 18
      when 'growth' then 38
      when 'custom' then public.tenh_custom_plan_monthly_price(v_current_users,v_current_branches)
      else 0
    end
  ));
  v_effective:=now();

  if b.subscription_status='active' and b.subscription_expires_at>now() then
    if (v_target_users>=v_current_users and v_target_branches>=v_current_branches)
       and (v_target_users>v_current_users or v_target_branches>v_current_branches)
       and v_target_users>=v_active_users
       and v_target_branches>=v_active_branches then
      v_kind:='upgrade';
      -- Immediate expansions start now, but the customer never loses the
      -- remaining paid time from the current subscription.
      v_carryover_seconds:=greatest(
        0,
        floor(extract(epoch from (b.subscription_expires_at-now())))::bigint
      );
      v_proration_seconds:=v_carryover_seconds;
      if v_carryover_seconds>0 then v_carryover_source:='paid'; end if;
    else
      -- Smaller/equal changes begin after the existing paid term, so the
      -- remaining time is already preserved by effective_at.
      v_kind:='renewal';
      v_effective:=b.subscription_expires_at;
    end if;
  elsif b.subscription_status='trialing' and b.trial_expires_at>now() then
    -- Paid access can start immediately without throwing away unused trial time.
    v_kind:='activation';
    v_carryover_seconds:=greatest(
      0,
      floor(extract(epoch from (b.trial_expires_at-now())))::bigint
    );
    if v_carryover_seconds>0 then v_carryover_source:='trial'; end if;
  elsif b.subscription_status='expired' then
    v_kind:='reactivation';
  else
    v_kind:='activation';
  end if;

  -- term_months=0 means capacity-only: keep the existing paid expiry and charge
  -- only the added capacity for the exact remaining paid time. It is never
  -- valid for activation, reactivation, renewal, or a no-op selection.
  if p_term_months=0 then
    if v_kind<>'upgrade' then
      raise exception 'Keep current duration is available only for an immediate capacity upgrade.';
    end if;
    if v_target_users=v_current_users and v_target_branches=v_current_branches then
      raise exception 'Increase users or branches, or choose a duration to add.';
    end if;
  end if;

  v_discount:=case p_term_months when 3 then 5 when 6 then 8 when 12 then 10 else 0 end;
  v_subtotal:=v_monthly*p_term_months;
  v_term:=round(v_subtotal*(1-v_discount/100),2);
  -- For an immediate capacity expansion, charge only the monthly-price
  -- difference for the exact remaining paid seconds. The selected new duration
  -- is then billed once at the target configuration's normal term price.
  if v_kind='upgrade' then
    v_upgrade_proration:=round(
      greatest(0,v_monthly-v_current_monthly) * greatest(0,v_proration_seconds)::numeric / 2592000,
      2
    );
  else
    v_upgrade_proration:=0;
    v_proration_seconds:=0;
  end if;
  v_credit:=0;
  v_total:=round(v_term+v_upgrade_proration,2);

  update public.subscription_orders
  set status='cancelled',cancelled_at=now(),updated_at=now()
  where business_id=b.id and status in ('pending_payment','quote_requested');

  insert into public.subscription_orders(
    business_id,requested_by_user_id,plan_key,requested_user_limit,requested_branch_limit,
    base_plan_key,pricing_version,term_months,monthly_price,discount_percent,subtotal_amount,
    term_price_amount,remaining_credit_amount,total_amount,currency,status,order_kind,
    current_plan_key,current_user_limit,current_branch_limit,current_subscription_started_at,
    current_subscription_expires_at,current_cycle_value,pricing_locked_until,effective_at,
    activated_at,keep_member_ids,keep_branch_ids,carryover_seconds,carryover_source,
    current_monthly_price,upgrade_proration_seconds,upgrade_prorated_amount,extension_amount
  ) values(
    b.id,p_requesting_user_id,p_plan_key,v_target_users,v_target_branches,
    case when p_plan_key='custom' then v_matching_plan else p_plan_key end,7,p_term_months,
    v_monthly,v_discount,v_subtotal,v_term,v_credit,v_total,'USD','pending_payment',v_kind,
    b.subscription_plan_key,b.subscription_user_limit,v_current_branches,b.subscription_started_at,
    b.subscription_expires_at,b.subscription_cycle_value,now()+interval '24 hours',v_effective,
    null,p_keep_member_ids,p_keep_branch_ids,v_carryover_seconds,v_carryover_source,
    v_current_monthly,v_proration_seconds,v_upgrade_proration,v_term
  ) returning id into v_id;

  return query select v_id,'pending_payment'::text;
end; $function$

CREATE OR REPLACE FUNCTION public.tenh_apply_subscription_order(p_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.subscription_orders%rowtype;
  b public.businesses%rowtype;
  v_start timestamptz;
  v_expiry timestamptz;
  v_matched_plan text;
  v_url_free integer:=0;
  v_mode_free integer:=0;
  v_owner_ids uuid[]:='{}'::uuid[];
  v_keep_members uuid[]:='{}'::uuid[];
  v_keep_branches uuid[]:='{}'::uuid[];
  v_disabled_members uuid[]:='{}'::uuid[];
  v_disabled_branches uuid[]:='{}'::uuid[];
  v_pending_branches uuid[]:='{}'::uuid[];
  v_default_branch uuid;
  v_id uuid;
  v_count integer;
begin
  select * into o from public.subscription_orders where id=p_order_id for update;
  if not found then raise exception 'Subscription order not found.'; end if;
  if o.status<>'approved' then raise exception 'Only an approved subscription order can be applied.'; end if;
  if o.activated_at is not null then
    return jsonb_build_object('status','already_applied','activated_at',o.activated_at);
  end if;
  if o.effective_at is not null and o.effective_at>now() then
    raise exception 'This subscription order is not effective yet.';
  end if;

  select * into b from public.businesses where id=o.business_id for update;
  if not found then raise exception 'Business not found.'; end if;

  -- Mark first so any nested capacity trigger in this same transaction cannot
  -- recursively pick the same due order. A later error rolls this back too.
  update public.subscription_orders set activated_at=now(),updated_at=now() where id=o.id;

  v_start:=coalesce(o.effective_at,now());
  if o.order_kind='upgrade' and o.current_subscription_expires_at is not null and o.current_subscription_expires_at>v_start then
    -- Capacity-only upgrades keep the current expiry. If the owner also buys
    -- more duration, it starts after the exact existing paid expiry.
    if o.term_months=0 then
      v_expiry:=o.current_subscription_expires_at;
    else
      v_expiry:=o.current_subscription_expires_at+make_interval(months=>o.term_months);
    end if;
  else
    v_expiry:=v_start+make_interval(months=>o.term_months)+make_interval(secs=>greatest(0,coalesce(o.carryover_seconds,0))::double precision);
  end if;

  if o.plan_key='custom' and o.requested_branch_limit=1 then
    v_matched_plan:=case o.requested_user_limit when 1 then 'solo' when 5 then 'small_team' when 10 then 'growth' else null end;
  elsif o.plan_key in ('solo','small_team','growth') then
    v_matched_plan:=o.plan_key;
  else
    v_matched_plan:=null;
  end if;
  if coalesce(v_matched_plan,o.plan_key) in ('growth','custom') then
    v_url_free:=2; v_mode_free:=2;
  end if;

  -- Owner seats are never automatically disabled. Pending password setup still
  -- occupies a seat, matching the existing team-capacity rules.
  select coalesce(array_agg(m.id order by m.created_at,m.id),'{}'::uuid[])
    into v_owner_ids
  from public.business_members m
  where m.business_id=b.id
    and m.role::text='owner'
    and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'));

  if coalesce(cardinality(v_owner_ids),0)>o.requested_user_limit then
    raise exception 'Owner seats exceed the selected user limit. Contact TENH before this plan can be applied.';
  end if;
  v_keep_members:=v_owner_ids;

  -- Optional owner selection is honored first, after protected owners.
  for v_id in
    select m.id
    from unnest(coalesce(o.keep_member_ids,'{}'::uuid[])) with ordinality x(id,ord)
    join public.business_members m on m.id=x.id
    where m.business_id=b.id
      and m.role::text<>'owner'
      and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'))
    order by x.ord
  loop
    exit when coalesce(cardinality(v_keep_members),0)>=o.requested_user_limit;
    if not (v_id=any(v_keep_members)) then v_keep_members:=array_append(v_keep_members,v_id); end if;
  end loop;

  -- Fill remaining seats oldest-first. Therefore the default automatic rule
  -- disables the newest excess users.
  for v_id in
    select m.id from public.business_members m
    where m.business_id=b.id
      and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'))
      and not (m.id=any(v_keep_members))
    order by m.created_at,m.id
  loop
    exit when coalesce(cardinality(v_keep_members),0)>=o.requested_user_limit;
    v_keep_members:=array_append(v_keep_members,v_id);
  end loop;

  select coalesce(array_agg(m.id),'{}'::uuid[]) into v_disabled_members
  from public.business_members m
  where m.business_id=b.id
    and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'))
    and not (m.id=any(v_keep_members));

  update public.business_members
  set is_active=false,
      disabled_at=now(),
      disabled_reason='subscription_seat_limit',
      updated_at=now()
  where business_id=b.id and id=any(v_disabled_members);

  -- Main/default branch is always protected. If an older workspace somehow has
  -- no default, promote the oldest active branch before applying the plan.
  select l.id into v_default_branch
  from public.business_locations l
  where l.business_id=b.id and l.is_active and l.is_default
  order by l.created_at,l.id limit 1;

  if v_default_branch is null then
    select l.id into v_default_branch
    from public.business_locations l
    where l.business_id=b.id and l.is_active
    order by l.created_at,l.id limit 1;
    if v_default_branch is not null then
      update public.business_locations set is_default=(id=v_default_branch),updated_at=now()
      where business_id=b.id and is_active;
    end if;
  end if;
  if v_default_branch is null then raise exception 'An active Main Branch is required.'; end if;
  v_keep_branches:=array[v_default_branch];

  if o.requested_branch_limit<1 then raise exception 'At least one branch is required.'; end if;

  for v_id in
    select l.id
    from unnest(coalesce(o.keep_branch_ids,'{}'::uuid[])) with ordinality x(id,ord)
    join public.business_locations l on l.id=x.id
    where l.business_id=b.id and l.is_active and l.id<>v_default_branch
    order by x.ord
  loop
    exit when coalesce(cardinality(v_keep_branches),0)>=o.requested_branch_limit;
    if not (v_id=any(v_keep_branches)) then v_keep_branches:=array_append(v_keep_branches,v_id); end if;
  end loop;

  -- Fill remaining branch capacity oldest-first; newest excess branches are the
  -- automatic disable candidates when the owner makes no custom selection.
  for v_id in
    select l.id from public.business_locations l
    where l.business_id=b.id and l.is_active and not (l.id=any(v_keep_branches))
    order by l.is_default desc,l.created_at,l.id
  loop
    exit when coalesce(cardinality(v_keep_branches),0)>=o.requested_branch_limit;
    v_keep_branches:=array_append(v_keep_branches,v_id);
  end loop;

  select coalesce(array_agg(l.id),'{}'::uuid[]) into v_disabled_branches
  from public.business_locations l
  where l.business_id=b.id and l.is_active and not (l.id=any(v_keep_branches));

  -- An excess branch with an open register is frozen for new operations but is
  -- left available long enough to close that register. The close trigger below
  -- finalizes the branch disable immediately afterward.
  foreach v_id in array v_disabled_branches loop
    if exists(select 1 from public.cash_register_shifts s where s.business_id=b.id and s.location_id=v_id and s.status='open') then
      update public.business_locations
      set plan_disable_pending=true,plan_disabled_at=now(),updated_at=now()
      where id=v_id and business_id=b.id;
      v_pending_branches:=array_append(v_pending_branches,v_id);
    else
      update public.business_locations
      set is_active=false,plan_disable_pending=false,plan_disabled_at=now(),updated_at=now()
      where id=v_id and business_id=b.id;
    end if;
  end loop;

  -- Kept users whose previous branch is being disabled continue safely on Main Branch.
  update public.business_members m
  set default_location_id=v_default_branch,updated_at=now()
  where m.business_id=b.id
    and (m.is_active or (coalesce(m.team_password_required,false) and m.disabled_reason='password_setup'))
    and m.default_location_id is not null
    and exists(
      select 1 from public.business_locations l
      where l.id=m.default_location_id and l.business_id=b.id
        and (not l.is_active or l.plan_disable_pending)
    );

  update public.businesses
  set subscription_plan_key=o.plan_key,
      subscription_base_plan_key=case when o.plan_key='custom' then v_matched_plan else o.plan_key end,
      subscription_user_limit=o.requested_user_limit,
      subscription_branch_limit=o.requested_branch_limit,
      subscription_team_enabled=o.requested_user_limit>1,
      max_staff=greatest(0,o.requested_user_limit-1),
      subscription_monthly_price=o.monthly_price,
      subscription_discount_percent=case when o.term_months=0 then coalesce(b.subscription_discount_percent,0) else o.discount_percent end,
      subscription_cycle_value=case when o.term_months=0 then
        round(o.monthly_price*greatest(1,coalesce(b.subscription_months,1))*(1-(case coalesce(b.subscription_months,1) when 3 then 5 when 6 then 8 when 12 then 10 else 0 end)/100.0),2)
        else o.term_price_amount end,
      subscription_months=case when o.term_months=0 then b.subscription_months else o.term_months end,
      subscription_status='active',
      subscription_started_at=case when o.order_kind='upgrade' then coalesce(b.subscription_started_at,v_start) else v_start end,
      subscription_expires_at=v_expiry,
      free_url_changes_per_month=v_url_free,
      free_business_mode_changes_per_month=v_mode_free,
      is_active=true,
      disabled_reason=null,
      disabled_at=null,
      expired_at=null,
      deletion_scheduled_at=null,
      scheduled_deletion_at=null,
      updated_at=now()
  where id=b.id;

  insert into public.subscription_history(
    business_id,action,months,months_added,previous_expiry,new_expiry,reason,created_by
  ) values(
    b.id,'extended',o.term_months,o.term_months,b.subscription_expires_at,v_expiry,
    'Subscription plan applied from payment '||o.id::text||case when coalesce(o.carryover_seconds,0)>0 then ' with preserved remaining access time' else '' end,o.reviewed_by_user_id
  );

  -- Keep a business-visible audit trail of the actual entitlement transition.
  -- The metadata records every automatic user/branch disable while preserving
  -- the underlying rows and historical activity.
  insert into public.audit_logs(
    business_id,user_id,action,entity_type,entity_id,description,metadata
  ) values(
    b.id,coalesce(o.requested_by_user_id,o.reviewed_by_user_id),
    'subscription_plan_applied','business',b.id,
    'Applied the paid subscription plan and enforced its active user and branch limits.',
    jsonb_build_object(
      'subscription_order_id',o.id,
      'previous_plan_key',b.subscription_plan_key,
      'new_plan_key',o.plan_key,
      'previous_user_limit',b.subscription_user_limit,
      'new_user_limit',o.requested_user_limit,
      'previous_branch_limit',coalesce(b.subscription_branch_limit,1),
      'new_branch_limit',o.requested_branch_limit,
      'effective_at',v_start,
      'new_expiry',v_expiry,
      'requested_by_user_id',o.requested_by_user_id,
      'reviewed_by_user_id',o.reviewed_by_user_id,
      'disabled_member_ids',to_jsonb(v_disabled_members),
      'disabled_branch_ids',to_jsonb(v_disabled_branches),
      'pending_branch_ids',to_jsonb(v_pending_branches),
      'carryover_seconds',coalesce(o.carryover_seconds,0),
      'carryover_source',coalesce(o.carryover_source,'none'),
      'upgrade_proration_seconds',coalesce(o.upgrade_proration_seconds,0),
      'upgrade_prorated_amount',coalesce(o.upgrade_prorated_amount,0),
      'extension_amount',coalesce(o.extension_amount,o.term_price_amount)
    )
  );

  return jsonb_build_object(
    'status','applied',
    'new_expiry',v_expiry,
    'disabled_member_ids',v_disabled_members,
    'disabled_branch_ids',v_disabled_branches,
    'pending_branch_ids',v_pending_branches
  );
end; $function$

CREATE OR REPLACE FUNCTION public.review_safe_subscription_order(p_order_id uuid, p_decision text, p_admin_user_id uuid, p_admin_email text, p_review_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.subscription_orders%rowtype;
  b public.businesses%rowtype;
  v_monthly numeric;
  v_discount numeric;
  v_matched text;
  v_apply jsonb;
  v_expected_proration numeric:=0;
  v_expected_proration_seconds bigint:=0;
begin
  if coalesce(auth.role(),'')<>'service_role' or not exists(
    select 1 from public.profiles where id=p_admin_user_id and role='super_admin' and is_active
  ) then raise exception 'Super Admin server access required.'; end if;
  select * into o from public.subscription_orders where id=p_order_id for update;
  if not found or o.pricing_version not in (5,6,7) then raise exception 'Safe subscription order not found.'; end if;
  select * into b from public.businesses where id=o.business_id for update;
  if p_decision='approve' and o.status='approved' then
    return jsonb_build_object('status','approved','alreadyReviewed',true,'effective_at',o.effective_at,'new_expiry',b.subscription_expires_at);
  end if;
  if p_decision='reject' and o.status='rejected' then
    return jsonb_build_object('status','rejected','alreadyReviewed',true);
  end if;
  if p_decision not in ('approve','reject') or o.status<>'payment_submitted' then
    raise exception 'Only a submitted payment can be reviewed.';
  end if;
  if p_decision='reject' then
    update public.subscription_orders set status='rejected',rejected_at=now(),reviewed_at=now(),reviewed_by_user_id=p_admin_user_id,reviewed_by_email=p_admin_email,review_note=p_review_note,updated_at=now() where id=o.id;
    return jsonb_build_object('status','rejected');
  end if;
  if o.payment_note is null or o.proof_bucket is null or o.proof_path is null or o.total_amount<0.50 then
    raise exception 'Payment note, proof and valid amount are required.';
  end if;
  if not b.is_active and coalesce(b.disabled_reason,'')<>'subscription_expired' then
    raise exception 'Resolve the business suspension before payment approval.';
  end if;
  if b.subscription_user_limit is distinct from o.current_user_limit
     or b.subscription_plan_key is distinct from o.current_plan_key
     or b.subscription_started_at is distinct from o.current_subscription_started_at
     or b.subscription_expires_at is distinct from o.current_subscription_expires_at then
    raise exception 'Subscription changed after checkout. Recreate the payment order.';
  end if;
  if o.order_kind='upgrade' and o.current_monthly_price is not null and b.subscription_monthly_price is not null
     and o.current_monthly_price is distinct from b.subscription_monthly_price then
    raise exception 'Subscription price changed after checkout. Recreate the payment order.';
  end if;

  if o.plan_key='solo' then v_monthly:=10;
  elsif o.plan_key='small_team' then v_monthly:=18;
  elsif o.plan_key='growth' then v_monthly:=38;
  elsif o.plan_key='custom' then
    v_matched:=case when o.requested_branch_limit=1 then case o.requested_user_limit when 1 then 'solo' when 5 then 'small_team' when 10 then 'growth' else null end else null end;
    if o.pricing_version=5 then
      -- Existing submitted v5 orders keep the price that was locked when the
      -- customer created them, so payment review remains safe and predictable.
      v_monthly:=case v_matched when 'solo' then 10 when 'small_team' then 18 when 'growth' then 38 else o.requested_user_limit*5+o.requested_branch_limit*20 end;
    else
      v_monthly:=public.tenh_custom_plan_monthly_price(o.requested_user_limit,o.requested_branch_limit);
    end if;
  else raise exception 'Invalid subscription plan.';
  end if;
  v_discount:=case o.term_months when 3 then 5 when 6 then 8 when 12 then 10 else 0 end;
  if o.order_kind='upgrade' and o.current_monthly_price is not null then
    v_expected_proration_seconds:=greatest(
      0,
      floor(extract(epoch from (o.current_subscription_expires_at-o.created_at)))::bigint
    );
    if abs(coalesce(o.upgrade_proration_seconds,0)-v_expected_proration_seconds)>5 then
      raise exception 'Upgrade proration window does not match the locked subscription expiry.';
    end if;
    v_expected_proration:=round(
      greatest(0,v_monthly-coalesce(o.current_monthly_price,0)) * greatest(0,coalesce(o.upgrade_proration_seconds,0))::numeric / 2592000,
      2
    );
  end if;
  if o.term_months not in (0,1,3,6,12)
     or o.requested_user_limit not between 1 and 500
     or o.requested_branch_limit not between 1 and 100
     or o.monthly_price<>v_monthly
     or o.discount_percent<>v_discount
     or o.subtotal_amount<>v_monthly*o.term_months
     or o.term_price_amount<>round(o.subtotal_amount*(1-v_discount/100),2)
     or coalesce(o.extension_amount,o.term_price_amount)<>o.term_price_amount
     or coalesce(o.upgrade_prorated_amount,0)<>v_expected_proration
     or o.remaining_credit_amount<0
     or o.total_amount<>round(o.term_price_amount-o.remaining_credit_amount+v_expected_proration,2) then
    raise exception 'Subscription pricing does not match its configuration.';
  end if;
  if o.order_kind='renewal' and o.remaining_credit_amount<>0 then raise exception 'Next-plan renewal cannot use current-term credit.'; end if;

  update public.subscription_orders
  set status='approved',approved_at=now(),reviewed_at=now(),reviewed_by_user_id=p_admin_user_id,
      reviewed_by_email=p_admin_email,review_note=p_review_note,updated_at=now()
  where id=o.id;

  if coalesce(o.effective_at,now())<=now() then
    v_apply:=public.tenh_apply_subscription_order(o.id);
    return jsonb_build_object('status','approved','effective_at',o.effective_at,'new_expiry',v_apply->>'new_expiry');
  end if;

  return jsonb_build_object('status','approved','effective_at',o.effective_at,'new_expiry',b.subscription_expires_at);
end; $function$

CREATE OR REPLACE FUNCTION public.update_pending_upgrade_billing_term(p_business_id uuid, p_requesting_user_id uuid, p_order_id uuid, p_term_months integer)
 RETURNS TABLE(order_id uuid, order_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.subscription_orders%rowtype;
  v_monthly numeric;
  v_discount numeric;
  v_subtotal numeric;
  v_term numeric;
  v_proration numeric;
  v_total numeric;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Server access required.';
  end if;

  if p_term_months not in (0,1,3,6,12) then
    raise exception 'Choose a valid billing term.';
  end if;

  if not exists (
    select 1
    from public.business_members
    where business_id = p_business_id
      and user_id = p_requesting_user_id
      and role::text = 'owner'
      and is_active
  ) then
    raise exception 'Business owner access required.';
  end if;

  select *
  into o
  from public.subscription_orders
  where id = p_order_id
    and business_id = p_business_id
  for update;

  if not found then
    raise exception 'Upgrade payment request was not found.';
  end if;

  if o.pricing_version <> 7 or o.order_kind <> 'upgrade' then
    raise exception 'Create a fresh upgrade request before changing this billing term.';
  end if;

  if o.status <> 'pending_payment' or o.payment_expired_at is not null then
    raise exception 'This upgrade is no longer waiting for payment.';
  end if;

  if o.payment_method is not null
     or o.payment_provider is not null
     or o.payway_tran_id is not null
     or o.proof_path is not null then
    raise exception 'Billing term is locked after payment starts.';
  end if;

  if p_term_months = 0 then
    if coalesce(o.current_user_limit, 0) >= coalesce(o.requested_user_limit, 0)
       and coalesce(o.current_branch_limit, 0) >= coalesce(o.requested_branch_limit, 0) then
      raise exception 'Keep current is available only when users or branches are being upgraded.';
    end if;
  end if;

  if o.plan_key = 'solo' then
    v_monthly := 10;
  elsif o.plan_key = 'small_team' then
    v_monthly := 18;
  elsif o.plan_key = 'growth' then
    v_monthly := 38;
  elsif o.plan_key = 'custom' then
    if o.requested_user_limit is null
       or o.requested_user_limit not between 1 and 500
       or o.requested_branch_limit is null
       or o.requested_branch_limit not between 1 and 100 then
      raise exception 'Choose valid Custom Plan user and branch counts.';
    end if;
    v_monthly := public.tenh_custom_plan_monthly_price(
      o.requested_user_limit,
      o.requested_branch_limit
    );
  else
    raise exception 'Invalid subscription plan.';
  end if;

  v_discount := case p_term_months
    when 3 then 5
    when 6 then 8
    when 12 then 10
    else 0
  end;

  v_subtotal := v_monthly * p_term_months;
  v_term := round(v_subtotal * (1 - v_discount / 100), 2);
  v_proration := round(
    greatest(0, v_monthly - greatest(0, coalesce(o.current_monthly_price, 0)))
      * greatest(0, coalesce(o.upgrade_proration_seconds, 0))::numeric
      / 2592000,
    2
  );
  v_total := round(v_term + v_proration, 2);

  update public.subscription_orders
  set term_months = p_term_months,
      monthly_price = v_monthly,
      discount_percent = v_discount,
      subtotal_amount = v_subtotal,
      term_price_amount = v_term,
      extension_amount = v_term,
      remaining_credit_amount = 0,
      upgrade_prorated_amount = v_proration,
      total_amount = v_total,
      updated_at = now()
  where id = o.id
    and business_id = p_business_id
    and status = 'pending_payment'
    and payment_expired_at is null
    and payment_method is null
    and payment_provider is null
    and payway_tran_id is null
    and proof_path is null;

  if not found then
    raise exception 'Billing term is locked because payment has already started.';
  end if;

  return query select o.id, 'pending_payment'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_pending_subscription_billing_term(p_business_id uuid, p_requesting_user_id uuid, p_order_id uuid, p_term_months integer)
 RETURNS TABLE(order_id uuid, order_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  o public.subscription_orders%rowtype;
  discount numeric;
  subtotal numeric;
  total numeric;
begin
  if coalesce(auth.role(),'') <> 'service_role' then raise exception 'Server access required.'; end if;
  -- Use the same business -> order lock order as checkout creation.
  perform 1 from public.businesses where id=p_business_id for update;
  if not exists(select 1 from public.business_members where business_id=p_business_id
    and user_id=p_requesting_user_id and role::text='owner' and is_active) then
    raise exception 'Business owner access required.';
  end if;
  select * into o from public.subscription_orders where id=p_order_id and business_id=p_business_id for update;
  if not found then raise exception 'Payment request was not found.'; end if;
  if o.status <> 'pending_payment' or o.payment_expired_at is not null
    or coalesce(o.payment_expires_at, o.created_at + interval '10 minutes') <= now()
    or o.pricing_locked_until <= now() then
    raise exception 'This payment request expired or is no longer waiting for payment.';
  end if;
  if o.payment_method is not null or o.payment_provider is not null
    or o.payway_tran_id is not null or o.proof_path is not null then
    raise exception 'Billing term is locked after payment starts.';
  end if;
  if o.order_kind = 'upgrade' then
    return query select * from public.update_pending_upgrade_billing_term(p_business_id,p_requesting_user_id,p_order_id,p_term_months);
    return;
  end if;
  if o.order_kind is distinct from 'reactivation' or o.pricing_version is distinct from 7 then
    raise exception 'Create a fresh reactivation checkout to change the billing term.';
  end if;
  if p_term_months is null or p_term_months not in (1,3,6,12) then raise exception 'Choose 1, 3, 6 or 12 months.'; end if;
  if o.monthly_price is null or o.monthly_price <= 0 then raise exception 'This quote has no valid monthly price.'; end if;
  discount := case p_term_months when 3 then 5 when 6 then 8 when 12 then 10 else 0 end;
  subtotal := o.monthly_price * p_term_months;
  total := round(subtotal * (1-discount/100),2);
  update public.subscription_orders set term_months=p_term_months, discount_percent=discount,
    subtotal_amount=subtotal, term_price_amount=total, extension_amount=total,
    total_amount=total, remaining_credit_amount=0, upgrade_prorated_amount=0, updated_at=now()
    where id=o.id;
  return query select o.id, 'pending_payment'::text;
end;
$function$
